<?php

use App\Http\Controllers\Api\MobileAuthController;
use App\Http\Controllers\Api\MobileCatalogController;
use App\Http\Controllers\Api\MobileAccountController;
use App\Http\Controllers\Api\MobileBookingController;
use App\Http\Controllers\Api\MobileAdminController;
use App\Http\Controllers\Api\MobilePassportController;
use App\Http\Controllers\Api\MobileExtendedController;
use App\Http\Controllers\PartRequestController;
use App\Http\Middleware\AuthenticateMobileToken;
use Illuminate\Support\Facades\Route;

Route::prefix('mobile')->group(function () {
    Route::post('/register', [MobileAuthController::class, 'register'])->middleware('throttle:3,1');
    Route::post('/login', [MobileAuthController::class, 'login'])->middleware('throttle:5,1');
    Route::get('/motorcycles', [MobileCatalogController::class, 'motorcycles']);
    Route::get('/parts', [MobileCatalogController::class, 'parts']);
    Route::get('/part-listings', [MobileCatalogController::class, 'partListings']);
    Route::get('/rentals', [MobileCatalogController::class, 'rentals']);
    Route::get('/service-centers', [MobileCatalogController::class, 'serviceCenters']);
    Route::get('/motorcycles/{motorcycle}/passport', [MobilePassportController::class, 'show'])->whereNumber('motorcycle');

    Route::middleware(AuthenticateMobileToken::class)->group(function () {
        Route::get('/garage', [MobileExtendedController::class, 'garage']);
        Route::post('/garage/reminders', [MobileExtendedController::class, 'storeReminder'])->middleware('throttle:10,1');
        Route::patch('/garage/reminders/{reminder}/complete', [MobileExtendedController::class, 'completeReminder'])->whereNumber('reminder');
        Route::post('/garage/expenses', [MobileExtendedController::class, 'storeExpense'])->middleware('throttle:10,1');
        Route::delete('/garage/expenses/{expense}', [MobileExtendedController::class, 'deleteExpense'])->whereNumber('expense');
        Route::get('/favorites', [MobileExtendedController::class, 'favorites']);
        Route::post('/favorites/motorcycles/{motorcycle}', [MobileExtendedController::class, 'toggleMotorcycleFavorite'])->whereNumber('motorcycle');
        Route::post('/favorites/parts/{source}/{part}', [MobileExtendedController::class, 'togglePartFavorite'])->whereIn('source', ['store', 'marketplace'])->whereNumber('part');
        Route::get('/compare', [MobileExtendedController::class, 'compare']);
        Route::get('/community', [MobileExtendedController::class, 'community']);
        Route::post('/community/posts', [MobileExtendedController::class, 'storePost'])->middleware('throttle:10,1');
        Route::post('/community/posts/{post}/comments', [MobileExtendedController::class, 'commentPost'])->whereNumber('post')->middleware('throttle:20,1');
        Route::post('/community/posts/{post}/like', [MobileExtendedController::class, 'likePost'])->whereNumber('post');
        Route::delete('/community/posts/{post}', [MobileExtendedController::class, 'deletePost'])->whereNumber('post');
        Route::get('/clubs', [MobileExtendedController::class, 'clubs']);
        Route::post('/clubs', [MobileExtendedController::class, 'storeClub'])->middleware('throttle:5,1');
        Route::post('/clubs/{club}/join', [MobileExtendedController::class, 'joinClub'])->whereNumber('club');
        Route::post('/clubs/{club}/members/{member}/approve', [MobileExtendedController::class, 'approveClubMember'])->whereNumber('club')->whereNumber('member');
        Route::post('/clubs/{club}/events', [MobileExtendedController::class, 'storeEvent'])->whereNumber('club')->middleware('throttle:5,1');
        Route::post('/events/{event}/attend', [MobileExtendedController::class, 'attendEvent'])->whereNumber('event');
        Route::get('/conversations', [MobileExtendedController::class, 'conversations']);
        Route::get('/conversations/{conversation}', [MobileExtendedController::class, 'conversation'])->whereNumber('conversation');
        Route::post('/conversations', [MobileExtendedController::class, 'startConversation'])->middleware('throttle:10,1');
        Route::post('/conversations/{conversation}/messages', [MobileExtendedController::class, 'sendMessage'])->whereNumber('conversation')->middleware('throttle:30,1');
        Route::get('/transport/account', [MobileExtendedController::class, 'transportIndex']);
        Route::post('/transport/requests', [MobileExtendedController::class, 'storeTransportRequest'])->middleware('throttle:5,1');
        Route::post('/transport/offers/{offer}/accept', [MobileExtendedController::class, 'acceptTransportOffer'])->whereNumber('offer');
        Route::get('/transport/partner', [MobileExtendedController::class, 'transportPartnerDashboard']);
        Route::post('/transport/partner/requests/{transportRequest}/offers', [MobileExtendedController::class, 'createTransportOffer'])->whereNumber('transportRequest')->middleware('throttle:10,1');
        Route::patch('/transport/partner/requests/{transportRequest}/status', [MobileExtendedController::class, 'updateTransportOrderStatus'])->whereNumber('transportRequest');
        Route::post('/moto-assistant/diagnose', [MobileExtendedController::class, 'diagnose'])->middleware('throttle:10,1');
        Route::get('/service-center/dashboard', [MobileExtendedController::class, 'serviceCenterDashboard']);
        Route::patch('/service-center/bookings/{booking}/status', [MobileExtendedController::class, 'updateServiceBookingStatus'])->whereNumber('booking');
        Route::post('/service-center/technicians', [MobileExtendedController::class, 'storeTechnician'])->middleware('throttle:10,1');
        Route::post('/service-center/bays', [MobileExtendedController::class, 'storeBay'])->middleware('throttle:10,1');
        Route::post('/service-center/inventory', [MobileExtendedController::class, 'storeInventory'])->middleware('throttle:10,1');
        Route::patch('/service-center/work-orders/{workOrder}/assignment', [MobileExtendedController::class, 'assignWorkOrder'])->whereNumber('workOrder');
        Route::post('/service-center/work-orders/{workOrder}/parts', [MobileExtendedController::class, 'addWorkOrderPart'])->whereNumber('workOrder');
        Route::post('/service-center/work-orders/{workOrder}/payments', [MobileExtendedController::class, 'recordWorkOrderPayment'])->whereNumber('workOrder');
        Route::patch('/service-center/work-orders/{workOrder}/status', [MobileExtendedController::class, 'updateWorkOrderStatus'])->whereNumber('workOrder');
        Route::get('/workshop/dashboard', [MobileExtendedController::class, 'workshopDashboard']);
        Route::post('/workshop/customers', [MobileExtendedController::class, 'storeWorkshopCustomer'])->middleware('throttle:10,1');
        Route::post('/workshop/customers/{customer}/motorcycles/{motorcycle}/service-records', [MobileExtendedController::class, 'storeWorkshopServiceRecord'])->whereNumber('customer')->whereNumber('motorcycle')->middleware('throttle:10,1');
        Route::get('/me', [MobileAccountController::class, 'show']);
        Route::get('/admin/dashboard', [MobileAdminController::class, 'dashboard']);
        Route::patch('/admin/{type}/{id}/status', [MobileAdminController::class, 'updateStatus'])->whereIn('type', ['motorcycles', 'part-requests', 'rental-bookings', 'service-bookings', 'service-centers'])->whereNumber('id')->middleware('throttle:30,1');
        Route::patch('/me', [MobileAccountController::class, 'update'])->middleware('throttle:10,1');
        Route::post('/logout', [MobileAuthController::class, 'logout']);
        Route::get('/my-listings', [MobileAccountController::class, 'listings']);
        Route::post('/my-listings', [MobileAccountController::class, 'storeListing'])->middleware('throttle:5,1');
        Route::put('/my-listings/{motorcycle}', [MobileAccountController::class, 'updateListing'])->middleware('throttle:10,1');
        Route::delete('/my-listings/{motorcycle}', [MobileAccountController::class, 'deleteListing'])->middleware('throttle:10,1');
        Route::get('/my-bookings', [MobileAccountController::class, 'bookings']);
        Route::post('/my-bookings/rentals/{booking}/cancel', [MobileAccountController::class, 'cancelRentalBooking'])->whereNumber('booking')->middleware('throttle:5,1');
        Route::post('/my-bookings/services/{booking}/cancel', [MobileAccountController::class, 'cancelServiceBooking'])->whereNumber('booking')->middleware('throttle:5,1');
        Route::post('/rentals/{rentalScooter:slug}/bookings', [MobileBookingController::class, 'rentalBooking'])->middleware('throttle:5,1');
        Route::post('/service-centers/{serviceCenter:slug}/bookings', [MobileBookingController::class, 'serviceBooking'])->middleware('throttle:5,1');
    });
});

Route::post('/part-requests', [PartRequestController::class, 'storeApi'])->middleware('throttle:5,1');
